-- TLMenu loading label (Dock style): paste this ABOVE the obfuscated code (unobfuscated).
-- Looks like Dock's top island + its splash branding. Shows right away while the
-- obfuscated Dock starts; removes itself once Dock's loading screen (DockSplash)
-- or the dock (DockGui) appears, or after 90 seconds. Never blocks the code below.
do
	local Players = game:GetService("Players")
	local TweenService = game:GetService("TweenService")
	local RunService = game:GetService("RunService")
	local player = Players.LocalPlayer
	local parent = (typeof(gethui) == "function" and gethui()) or (player and player:FindFirstChildOfClass("PlayerGui"))
	if parent then
		local old = parent:FindFirstChild("TLLoadingLabel")
		if old then old:Destroy() end

		-- Dock "Picture" theme + splash brand colours
		local SURFACE = Color3.fromRGB(20, 21, 24)
		local OUTLINE = Color3.fromRGB(52, 55, 60)
		local ACTIVE = Color3.fromRGB(46, 172, 255)
		local TEXT = Color3.fromRGB(236, 237, 240)
		local SUB = Color3.fromRGB(160, 163, 168)
		local BRAND = ColorSequence.new(Color3.fromRGB(0, 140, 255), Color3.fromRGB(0, 230, 150))
		local function face(weight, fallback)
			if typeof(Font) == "table" and typeof(Font.new) == "function" then
				local ok, f = pcall(Font.new, "rbxasset://fonts/families/BuilderSans.json", weight)
				if ok and f then return f end
			end
			return fallback
		end
		local function setFont(lbl, weight, fallback)
			local f = face(weight, fallback)
			if typeof(f) == "Font" then lbl.FontFace = f else lbl.Font = f end
		end

		local W, H = 330, 74
		local sg = Instance.new("ScreenGui")
		sg.Name = "TLLoadingLabel"
		sg.ResetOnSpawn = false
		sg.IgnoreGuiInset = true
		sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
		sg.DisplayOrder = 1001

		-- island card: same surface, outline, radius and spot as Dock's top island
		local card = Instance.new("Frame")
		card.AnchorPoint = Vector2.new(0.5, 0)
		card.Position = UDim2.new(0.5, 0, 0, -H - 30)
		card.Size = UDim2.fromOffset(W, H)
		card.BackgroundColor3 = SURFACE
		card.BorderSizePixel = 0
		card.ClipsDescendants = true
		card.Parent = sg
		Instance.new("UICorner", card).CornerRadius = UDim.new(0, 14)
		local stroke = Instance.new("UIStroke", card)
		stroke.Color = OUTLINE
		stroke.Thickness = 1
		stroke.Transparency = 0.25
		stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		-- scales with screen height like Dock (1080p = 1)
		local scale = Instance.new("UIScale", card)
		pcall(function()
			local vp = workspace.CurrentCamera.ViewportSize
			scale.Scale = math.clamp(vp.Y / 1080, 0.75, 1.5)
		end)

		-- TLMenu logo (same asset as Dock's loading screen), gently floating
		local logo = Instance.new("ImageLabel")
		logo.AnchorPoint = Vector2.new(0, 0.5)
		logo.Position = UDim2.new(0, 14, 0.5, -3)
		logo.Size = UDim2.fromOffset(38, 38)
		logo.BackgroundTransparency = 1
		logo.Image = "rbxassetid://89872178631966"
		logo.ScaleType = Enum.ScaleType.Fit
		logo.Parent = card

		local title = Instance.new("TextLabel")
		title.BackgroundTransparency = 1
		title.Position = UDim2.fromOffset(64, 15)
		title.Size = UDim2.new(1, -78, 0, 20)
		setFont(title, Enum.FontWeight.Bold, Enum.Font.GothamBold)
		title.TextSize = 17
		title.TextColor3 = Color3.new(1, 1, 1)
		title.TextXAlignment = Enum.TextXAlignment.Left
		title.Text = "TLMENU LOADS"
		title.Parent = card
		local tg = Instance.new("UIGradient", title)
		tg.Color = BRAND

		local sub = Instance.new("TextLabel")
		sub.BackgroundTransparency = 1
		sub.Position = UDim2.fromOffset(64, 36)
		sub.Size = UDim2.new(1, -78, 0, 16)
		setFont(sub, Enum.FontWeight.Medium, Enum.Font.GothamMedium)
		sub.TextSize = 13
		sub.TextColor3 = SUB
		sub.TextXAlignment = Enum.TextXAlignment.Left
		sub.Text = "can take up to 30 sec · please be patient"
		sub.Parent = card

		-- live status dot (island style), right side
		local dot = Instance.new("Frame")
		dot.AnchorPoint = Vector2.new(1, 0.5)
		dot.Position = UDim2.new(1, -16, 0, 25)
		dot.Size = UDim2.fromOffset(9, 9)
		dot.BackgroundColor3 = ACTIVE
		dot.BorderSizePixel = 0
		dot.Parent = card
		Instance.new("UICorner", dot).CornerRadius = UDim.new(1, 0)

		-- indeterminate loading bar (splash brand gradient) along the bottom
		local track = Instance.new("Frame")
		track.Position = UDim2.new(0, 64, 1, -14)
		track.Size = UDim2.new(1, -80, 0, 4)
		track.BackgroundColor3 = Color3.new(1, 1, 1)
		track.BackgroundTransparency = 0.9
		track.BorderSizePixel = 0
		track.ClipsDescendants = true
		track.Parent = card
		Instance.new("UICorner", track).CornerRadius = UDim.new(1, 0)
		local fill = Instance.new("Frame")
		fill.Size = UDim2.fromScale(0.35, 1)
		fill.BackgroundColor3 = Color3.new(1, 1, 1)
		fill.BorderSizePixel = 0
		fill.Parent = track
		Instance.new("UICorner", fill).CornerRadius = UDim.new(1, 0)
		Instance.new("UIGradient", fill).Color = BRAND

		sg.Parent = parent
		-- Dock's ENTER tween (Back out)
		TweenService:Create(card, TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
			{ Position = UDim2.new(0.5, 0, 0, 12) }):Play()

		local t0 = os.clock()
		local anim = RunService.RenderStepped:Connect(function()
			local t = os.clock() - t0
			fill.Position = UDim2.fromScale(((t * 0.6) % 1.35) - 0.35, 0) -- sweeps left -> right
			logo.Position = UDim2.new(0, 14, 0.5, -3 + math.sin(t * 2.2) * 2)
			dot.BackgroundTransparency = 0.35 - 0.35 * math.cos(t * 3)
			title.Text = "TLMENU LOADS" .. string.rep(".", math.floor(t * 2.5) % 4)
		end)

		-- remove once Dock is up (or after 90 s), with Dock's LEAVE tween
		task.spawn(function()
			local function dockUp()
				for _, root in ipairs({ parent, player and player:FindFirstChildOfClass("PlayerGui") }) do
					if root and (root:FindFirstChild("DockSplash") or root:FindFirstChild("DockGui")) then
						return true
					end
				end
				return false
			end
			while sg.Parent and not dockUp() and os.clock() - t0 < 90 do
				task.wait(0.25)
			end
			if sg.Parent then
				local tw = TweenService:Create(card, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
					{ Position = UDim2.new(0.5, 0, 0, -H - 30) })
				tw:Play()
				tw.Completed:Wait()
			end
			anim:Disconnect()
			sg:Destroy()
		end)
	end
end
